import { describeFeeRule } from "@/engine/fees";
import { FEE_CATEGORIES, type FeeRule, type FeeScheduleSnapshot } from "@/engine/fees/types";
import { CATEGORY_LABELS, resolveMinimumMembers } from "@/components/fees/shared";
import { cn } from "@/components/ui/cn";
import { formatDate } from "@/lib/format/date";

/**
 * A fee schedule exactly as the customer reads it: charges grouped by category, each in plain words
 * generated by `describeFeeRule` (the same text the editor previews), the account minimum with the
 * fees that count toward it, and the dates it is in effect.
 *
 * This is a Server Component and nothing it prints is internal: no rule keys, ids, version numbers,
 * staff notes or sources. It reads only the snapshot's customer-visible fields. The same component
 * renders the 3PL's "What your customer will read" preview, so what staff approve is what customers see.
 *
 * Headings: the host page supplies the h1 and the h2; categories are h3 and each charge is h4.
 */

type SnapshotLike = Omit<FeeScheduleSnapshot, "effectiveDate"> & { effectiveDate: string | null };

export function describeEffectivity(effective: string | null, expiration: string | null, audience: "brand" | "staff"): string {
  if (!effective) return audience === "staff" ? "Dates are set when this version is activated." : "";
  return expiration ? `In effect ${formatDate(effective)} – ${formatDate(expiration)}.` : `In effect from ${formatDate(effective)}, with no end date.`;
}

export function describeRounding(rounding: SnapshotLike["rounding"]): string {
  return rounding === "transaction" ? "The fee on each order is rounded to the nearest cent." : "Amounts are added up exactly across your orders and rounded to the nearest cent once per charge.";
}

function groupByCategory(rules: FeeRule[]) {
  return FEE_CATEGORIES.map((category) => ({ category, rules: rules.filter((r) => r.category === category) })).filter((g) => g.rules.length > 0);
}

export function FeeScheduleView({ snapshot, audience = "brand", idPrefix = "fees", className }: { snapshot: SnapshotLike; audience?: "brand" | "staff"; idPrefix?: string; className?: string }) {
  const rules = [...snapshot.rules].sort((a, b) => a.position - b.position || a.key.localeCompare(b.key));
  const byKey = new Map(rules.map((r) => [r.key, r]));
  const groups = groupByCategory(rules);
  const dates = describeEffectivity(snapshot.effectiveDate, snapshot.expirationDate, audience);

  if (!rules.length) {
    return <p className={cn("text-sm text-muted", className)}>{audience === "staff" ? "This version has no rules yet, so there is nothing for a customer to read." : "This fee schedule has no charges."}</p>;
  }

  return (
    <div className={cn("space-y-8", className)}>
      <div className="space-y-1 text-sm text-muted">
        {dates ? <p>{dates}</p> : null}
        <p>{describeRounding(snapshot.rounding)}</p>
      </div>
      {groups.map((group) => {
        const headingId = `${idPrefix}-cat-${group.category}`;
        return (
          <section key={group.category} aria-labelledby={headingId} className="space-y-3">
            <h3 id={headingId} className="text-base font-semibold tracking-tight">
              {CATEGORY_LABELS[group.category]}
            </h3>
            <ul className="divide-y divide-line overflow-hidden rounded-card border border-line bg-raised shadow-card">
              {group.rules.map((rule) => (
                <li key={rule.key} className="px-4 py-4 sm:px-6">
                  <RuleBlock rule={rule} rules={rules} byKey={byKey} audience={audience} />
                </li>
              ))}
            </ul>
          </section>
        );
      })}
    </div>
  );
}

function RuleBlock({ rule, rules, byKey, audience }: { rule: FeeRule; rules: FeeRule[]; byKey: Map<string, FeeRule>; audience: "brand" | "staff" }) {
  const alternatives = rule.exclusiveGroup ? rules.filter((o) => o.exclusiveGroup === rule.exclusiveGroup && o.key !== rule.key) : [];
  const asked = rule.driver && (rule.basis === "driver" || rule.basis === "order_driver") ? rule.driver : null;
  let members: FeeRule[] | null = null;
  let membersPending = false;
  if (rule.basis === "minimum" && rule.minimum) {
    if (rule.resolvedRuleKeys) members = rule.resolvedRuleKeys.map((k) => byKey.get(k)).filter((r): r is FeeRule => r !== undefined);
    else {
      members = resolveMinimumMembers(rules, rule.minimum);
      membersPending = true;
    }
  }
  return (
    <div className="space-y-1.5 [overflow-wrap:anywhere]">
      <h4 className="font-medium">{rule.name}</h4>
      <p className="text-[15px]">{describeFeeRule(rule)}</p>
      {rule.description ? <p className="text-sm text-muted">{rule.description}</p> : null}
      {asked ? (
        <p className="text-sm text-muted">
          Depends on what you tell us: {asked.label}
          {rule.helpText ? <span className="mt-0.5 block">{rule.helpText}</span> : null}
        </p>
      ) : rule.helpText ? (
        <p className="text-sm text-muted">{rule.helpText}</p>
      ) : null}
      {alternatives.length ? (
        <p className="text-sm text-muted">
          Only one of these applies each time: {[rule, ...alternatives].map((r) => r.name).join(", ")}.
        </p>
      ) : null}
      {members ? (
        <div className="text-sm">
          <p className="font-medium">Fees counted toward this minimum</p>
          {members.length ? (
            <ul className="mt-1 list-disc space-y-0.5 pl-5 text-muted">
              {members.map((m) => (
                <li key={m.key}>{m.name}</li>
              ))}
            </ul>
          ) : (
            <p className="text-muted">None.</p>
          )}
          {membersPending && audience === "staff" ? <p className="mt-1 text-muted">Which fees count is fixed when the version is activated.</p> : null}
        </div>
      ) : null}
    </div>
  );
}
